    25  const uint8_t *get_word(const uint8_t *data, size_t size)
    26  {
    27          /* Words are separated by one zero byte,
    28             return pointer to the next word if there is one */
    29          const uint8_t *ptr = data;
    30          if (!data || size == 0 || *data == 0)
    31                  return NULL;
    32
    33          ptr = memchr(data, 0, size - 1);
    34          return ptr ? ++ptr : NULL;
    35  }
    36
    37  char *extract_word(const uint8_t **data, size_t *size)
    38  {
    39          /* Find word and return its copy (needs to be freed) */
    40          char *result = NULL;
    41          const uint8_t *ptr = NULL;
    42
    43          if (*size < 2)
    44                  return NULL;
    45
    46          ptr = get_word(*data, *size);
    47          if (!ptr)
    48                  return NULL;
    49          result = strdup((const char *)*data);
    50          *size -=(ptr - *data);
    51          *data = ptr;
    52
    53          return result;
    54  }
