    56  int get_fuzzed_argv(const char *app_name, const uint8_t *data, size_t size,
    57                      char ***argv_out, int *argc_out, const uint8_t **reader_data, size_t *reader_data_size)
    58  {
    59          const uint8_t *ptr = data, *help_ptr = data;
    60          size_t ptr_size = size;
    61          char **argv = NULL;
    62          int argc = 1;
    63
    64          /* Count arguments until double zero bytes occurs*/
    65          while(*ptr != 0) {
    66                  ptr = get_word(help_ptr, ptr_size);
    67                  if (!ptr)
    68                          return -1;
    69                  argc++;
    70                  ptr_size -= (ptr - help_ptr);
    71                  help_ptr = ptr;
    72          }
    73
    74          if (argc > MAX_ARGC)
    75                  return -1;
    76
    77          argv = malloc((argc + 1) * sizeof(char*));
    78          if (!argv)
    79                  return -1;
    80
    81          /* Copy arguments into argv */
    82          ptr = data;
    83          ptr_size = size;
    84          argv[0] = strdup(app_name);
    85          for (int i = 1; i < argc; i++) {
    86                  argv[i] = extract_word(&ptr, &ptr_size);
